PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'owner',password_hash TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_invites(id TEXT PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,email TEXT NOT NULL,name TEXT NOT NULL,expires_at TEXT NOT NULL,used_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS devices(id TEXT PRIMARY KEY,name TEXT NOT NULL,platform TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,location TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,last_seen TEXT,health_json TEXT NOT NULL DEFAULT '{}',config_json TEXT NOT NULL DEFAULT '{}',revoked_at TEXT);
CREATE INDEX IF NOT EXISTS devices_last_seen ON devices(last_seen);
CREATE TABLE IF NOT EXISTS enrollments(id TEXT PRIMARY KEY,code_hash TEXT NOT NULL UNIQUE,name TEXT NOT NULL,platform TEXT NOT NULL,device_id TEXT,expires_at TEXT NOT NULL,consumed_at TEXT,claim_nonce TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS incidents(id TEXT PRIMARY KEY,device_id TEXT NOT NULL,client_event_id TEXT NOT NULL,risk_kind TEXT NOT NULL,model_state TEXT NOT NULL,severity INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'open',observed_frames INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL,occurred_at TEXT NOT NULL,received_at TEXT NOT NULL,updated_at TEXT NOT NULL,resolved_at TEXT,acknowledged_at TEXT,acknowledged_by TEXT,staff_requested_at TEXT,clock_warning INTEGER NOT NULL DEFAULT 0,summary TEXT NOT NULL DEFAULT '',UNIQUE(device_id,client_event_id));
CREATE INDEX IF NOT EXISTS incidents_updated ON incidents(updated_at DESC);
CREATE INDEX IF NOT EXISTS incidents_status ON incidents(status,severity);
CREATE TABLE IF NOT EXISTS incident_updates(id INTEGER PRIMARY KEY AUTOINCREMENT,incident_id TEXT NOT NULL,device_id TEXT NOT NULL,client_revision INTEGER,action TEXT NOT NULL,severity INTEGER NOT NULL,observed_frames INTEGER NOT NULL,actor TEXT NOT NULL,occurred_at TEXT NOT NULL,received_at TEXT NOT NULL,details_json TEXT NOT NULL DEFAULT '{}',UNIQUE(device_id,incident_id,client_revision));
CREATE TABLE IF NOT EXISTS snapshots(id TEXT PRIMARY KEY,incident_id TEXT NOT NULL,mime_type TEXT NOT NULL,bytes INTEGER NOT NULL,data_base64 TEXT NOT NULL,captured_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS snapshots_incident ON snapshots(incident_id,created_at DESC);
CREATE TABLE IF NOT EXISTS changes(seq INTEGER PRIMARY KEY AUTOINCREMENT,category TEXT NOT NULL,entity_id TEXT NOT NULL,action TEXT NOT NULL,data_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS push_subscriptions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,endpoint_hash TEXT NOT NULL UNIQUE,subscription_json TEXT NOT NULL,label TEXT NOT NULL,device_ids_json TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL,last_success TEXT,last_error TEXT);
CREATE TABLE IF NOT EXISTS notification_jobs(id TEXT PRIMARY KEY,incident_id TEXT,change_seq INTEGER,channel TEXT NOT NULL,target TEXT NOT NULL,payload_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_attempt INTEGER NOT NULL DEFAULT 0,lease_until INTEGER NOT NULL DEFAULT 0,provider_id TEXT,last_error TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(change_seq,channel,target));
CREATE INDEX IF NOT EXISTS notification_jobs_pending ON notification_jobs(status,next_attempt);
CREATE TABLE IF NOT EXISTS device_commands(id TEXT PRIMARY KEY,device_id TEXT NOT NULL,incident_id TEXT,kind TEXT NOT NULL,payload_json TEXT NOT NULL,created_at TEXT NOT NULL,acknowledged_at TEXT);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT,details_json TEXT NOT NULL,created_at TEXT NOT NULL);
